package com.skyclone.mod.fishing;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;

import java.io.Reader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The module's own data file, {@code data/fishing/fishing.json}, generated by
 * {@code tools/gen/fishing/gen_fishing.py}. Pure Java (Gson only) so the unit tests read the same
 * file the server does. Every class here is a plain Gson target: public fields, defaults in the
 * initialisers.
 */
public final class FishingCatalog {

    public List<Pool> pools = new ArrayList<>();
    public Map<String, Bait> baits = new LinkedHashMap<>();
    public Map<String, Part> parts = new LinkedHashMap<>();
    public Trophy trophy = new Trophy();
    public List<Catch> fish = new ArrayList<>();
    public List<Catch> lavaFish = new ArrayList<>();
    public Treasure treasure = new Treasure();
    public List<ShopEntry> keeperShop = new ArrayList<>();
    public List<ShopEntry> baitShop = new ArrayList<>();
    public List<ShopEntry> partShop = new ArrayList<>();
    public Map<String, Integer> hotspots = new LinkedHashMap<>();
    public Map<String, Integer> fsCaps = new HashMap<>();
    public Map<String, Rod> rods = new LinkedHashMap<>();
    /** The Bayou guide's seven chapters (audit 2026-10-06 F11). */
    public List<Chapter> jonesy = new ArrayList<>();

    public static final class Chapter {
        public String name;
        /** Fishing XP paid for EACH task of the chapter. */
        public double xp;
        public int sbXp;
        public List<TreasureEntry> rewards = new ArrayList<>();
        /** The last chapter's reward: the Pearl of the Swamp perk. */
        public boolean pearl;
        public List<Task> tasks = new ArrayList<>();
    }

    public static final class Task {
        public String kind;
        public String arg = "";
        public String label;
    }

    public static final class Pool {
        public String id;
        public String name;
        /** "water" or "lava". */
        public String liquid = "water";
        /** "base" (highest priority match is the pool), "add" (merged in), "replace" (swap chance). */
        public String mode = "base";
        public int priority;
        /** replace pools: base chance (0..1) that a rolled creature is swapped for one of these. */
        public double chance;
        /** replace pools: what switches it on ("festival", "spooky", "hotspot", "bait:X", "item:X", "zone:a|b"). */
        public String trigger;
        public List<String> islands = new ArrayList<>();
        public List<String> keywords = new ArrayList<>();
        public List<PoolCreature> creatures = new ArrayList<>();

        public boolean isBase() { return "base".equals(mode); }
        public boolean isAdd() { return "add".equals(mode); }
        public boolean isReplace() { return "replace".equals(mode); }
    }

    public static final class PoolCreature {
        public String mob;
        public double weight;
        /** Fishing level required. */
        public int level;
        /** Optional condition: "night", "day", "bait:X", "zone:a|b", "item:X", joined with '&'; '!' negates. */
        public String cond;
    }

    public static final class Bait {
        public double fs;
        public double scc;
        public double treasure;
        public double trophy;
        /** Multiplier on Fishing Speed (Corrupted Bait = 0.5). */
        public double fsMult = 1.0;
        public double rareDay;
        public double rareNight;
        public double rareAlways;
        public double spookyChance;
        public double sharkChance;
        public double hotspotChance;
        /** Extra chance (fraction) that a treasure is GREAT or OUTSTANDING. */
        public double blessed;
        public int chum;
        public boolean lavaOnly;
        public boolean wormsOnly;
        /** Only usable on this island (null = anywhere). */
        public String island;
        /** This bait is itself a trophy fish (the Obfuscated chain). */
        public String trophyBait;
    }

    public static final class Part {
        public String slot;
        public double commonWeight;
        public double hotspotChance;
        public double spookyChance;
        public double keepBait;
        public double hotspotMult;
        public double festive;
        public double damage;
        public boolean noCreatures;
        public boolean junk;
        public Map<String, Double> stats = new LinkedHashMap<>();
        public Map<String, Double> mobWeight = new LinkedHashMap<>();
        public List<String> materialize = new ArrayList<>();
    }

    public static final class Trophy {
        public LinkedHashMap<String, TrophyFish> fish = new LinkedHashMap<>();
        public Tiers tiers = new Tiers();
        public Map<String, Double> xp = new LinkedHashMap<>();
        public List<Title> titles = new ArrayList<>();
    }

    public static final class TrophyFish {
        public String name;
        public String rarity;
        /** Base catch chance in percent (null for Mana Ray / Golden Fish, which have their own rules). */
        public Double rate;
        public String cond;
        public Map<String, Integer> fillet = new LinkedHashMap<>();
        public String desc;
    }

    public static final class Tiers {
        public Map<String, Double> chances = new LinkedHashMap<>();
        public Map<String, Integer> pity = new LinkedHashMap<>();
        public Map<String, Double> xpMult = new LinkedHashMap<>();
    }

    public static final class Title {
        public int level;
        public String name;
        public String tier;
    }

    public static final class Catch {
        public String item;
        public double weight;
        public double xp;
    }

    public static final class Treasure {
        public Map<String, Double> weights = new LinkedHashMap<>();
        public Map<String, Double> xp = new LinkedHashMap<>();
        public Map<String, List<TreasureEntry>> water = new LinkedHashMap<>();
        public Map<String, Map<String, List<TreasureEntry>>> islands = new LinkedHashMap<>();
        public Map<String, List<TreasureEntry>> junk = new LinkedHashMap<>();
        /** The Junk Sinker's own tier split (research: Good 89 / Great 10 / Outstanding 1); empty = {@link #weights}. */
        public Map<String, Double> junkWeights = new LinkedHashMap<>();

        /** The tier weights for this catch: junk has its own split. */
        public Map<String, Double> weightsFor(boolean junk) {
            return junk && junkWeights != null && !junkWeights.isEmpty() ? junkWeights : weights;
        }
    }

    public static final class TreasureEntry {
        public String item;
        public int min = 1;
        public int max = 1;
        public double weight = 10;
    }

    public static final class ShopEntry {
        public String item;
        public double coins;
        /** Trophy Keeper only: trophy title level needed (0 = none). */
        public int title;
    }

    public static final class Rod {
        public boolean lava;
    }

    // ---- loading --------------------------------------------------------------------------------

    private static final Gson GSON = new GsonBuilder().create();

    public static FishingCatalog read(Reader r) {
        FishingCatalog c = GSON.fromJson(r, FishingCatalog.class);
        return c == null ? new FishingCatalog() : c;
    }

    // ---- lookups ---------------------------------------------------------------------------------

    public Pool pool(String id) {
        for (Pool p : pools) if (p.id.equals(id)) return p;
        return null;
    }

    /** Fishing Speed cap for an island (research 07 §3.2: Bayou 200, Crimson 350, else the default). */
    public int fsCap(String island, int fallback) {
        Integer v = island == null ? null : fsCaps.get(island);
        return v == null ? fallback : v;
    }

    public static final String[] TIERS = {"BRONZE", "SILVER", "GOLD", "DIAMOND"};

    public static int tierIndex(String tier) {
        for (int i = 0; i < TIERS.length; i++) if (TIERS[i].equalsIgnoreCase(tier)) return i;
        return -1;
    }
}
